style.css:
/* ♡ Strawberry Doll — Roblox */

:root {
  --my-pink: #f4b6ca;
  --my-light-pink: #ffe5ed;
  --my-blush: #fff4f7;
  --my-white: #fffafd;
  --my-rose: #d987a5;
  --my-text: #805768;
  --my-border: #f3cbd8;
}

/* your uploaded cute font */
@font-face {
  font-family: "Strawberry Cute";
  src: local("lim 6");
  font-weight: normal;
}

/* apply cute font everywhere */
body,
body * {
  font-family: "Strawberry Cute", sans-serif !important;
}

/* page background */
body {
  background: linear-gradient(
    135deg,
    var(--my-blush),
    var(--my-light-pink)
  ) !important;
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-rose) !important;
}

/* buttons */
button,
input[type="button"],
input[type="submit"] {
  background: var(--my-pink) !important;
  color: white !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 3px 10px #e9b4c655 !important;
}

/* button hover */
button:hover {
  background: var(--my-rose) !important;
}

/* input boxes */
input,
textarea,
select {
  background: var(--my-white) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 10px !important;
}

/* rounded images */
img {
  border-radius: 10px !important;
}

/* text selection */
::selection {
  background: var(--my-pink);
  color: white;
}

/* scrollbar */
::-webkit-scrollbar {
  width: 9px;
}

::-webkit-scrollbar-track {
  background: var(--my-blush);
}

::-webkit-scrollbar-thumb {
  background: var(--my-pink);
  border-radius: 20px;
}
